// Grade 6 to 8 English lessons, in the shape of lessons-english.js: [title, intro, points, example, steps, tip].
export const MIDDLE_ENGLISH_LESSONS = {
  /* ---------- reading literature ---------- */
  "Theme and central idea": ["Theme and Central Idea", "Theme is a story's message about life; central idea is what an informational text is mostly about.", ["Theme is a full sentence, not one word: \"Courage means acting despite fear.\"", "Watch how the main character changes and what they learn.", "Central idea is supported by key details.", "Both are usually implied, not stated."], "A girl lies to win a race, feels miserable and returns the medal. What is the theme?", ["What does she learn? Winning dishonestly feels empty.", "Theme: honesty matters more than winning."], "Ask: What does the author want me to understand about life?"],
  "Plot development": ["Plot Development", "Plot is the sequence of events, built around a conflict.", ["Exposition: characters and setting.", "Rising action: complications build.", "Climax: the turning point.", "Falling action and resolution: the conflict settles."], "In a story, a boy enters a contest, faces setbacks and wins on the final try. Where is the climax?", ["The climax is the moment of highest tension.", "His final try, when the outcome is decided."], "Each event should push the conflict forward."],
  "Character development": ["Character Development", "Characters reveal themselves through what they say, do and think, and how others react.", ["Direct characterization: the author tells you (\"Mia was brave\").", "Indirect: you infer from actions and words.", "Dynamic characters change; static characters don't."], "\"Leo pocketed the last cookie and blamed his sister.\" What trait is shown?", ["Leo takes the cookie and lies.", "He is selfish and dishonest."], "Track how a character changes from beginning to end."],
  "How ideas are developed": ["How Ideas Develop", "Authors build a central idea step by step with details, examples and explanations.", ["Introduce the idea.", "Support it with facts, examples and anecdotes.", "Connect paragraphs with transitions.", "Conclude by reinforcing the idea."], "An article on sleep opens with a teen falling asleep in class, then gives research. Why?", ["The anecdote hooks readers and shows the problem.", "The research supports it with evidence."], "Notice how each paragraph adds to the central idea."],
  "Author's point of view": ["Author's Point of View", "An author's point of view is their attitude or position on a topic.", ["Look for opinion words and loaded language.", "Notice which facts the author includes or leaves out.", "Ask how the author wants you to feel."], "An author calls a new park \"a priceless gift to the city.\" What is their view?", ["\"Priceless gift\" is strongly positive.", "The author supports the park."], "Point of view is shown in word choice."],
  "Citing several pieces of evidence": ["Several Pieces of Evidence", "Strong answers use more than one piece of text evidence.", ["Find two or three quotations that support your idea.", "Introduce each one: \"The author writes…\"", "Explain how each one supports your claim."], "Claim: The narrator is lonely. Find two pieces of evidence.", ["\"She ate lunch alone again.\"", "\"No one noticed when she left.\"", "Both show she is isolated."], "Use evidence from different parts of the text."],
  "Two or more central ideas": ["More Than One Central Idea", "Complex texts often develop two or more central ideas.", ["Look at headings and topic sentences.", "Each central idea has its own supporting details.", "Notice how the ideas connect."], "An article explains how bees make honey and how pesticides harm bees. What are the central ideas?", ["Idea 1: how bees make honey.", "Idea 2: threats to bees.", "They connect: honey depends on healthy bees."], "A good summary includes every central idea."],
  "Theme development": ["How Theme Develops", "A theme grows across a story through characters, conflict and resolution.", ["Notice early hints of the theme.", "Watch how the conflict tests the main character.", "The resolution often shows the theme clearly."], "A shy boy avoids the stage, practices secretly and finally performs. How does the theme develop?", ["Beginning: fear holds him back.", "Middle: he practices despite fear.", "End: he performs. Theme: courage grows through practice."], "Trace the theme at the beginning, middle and end."],
  "How story elements interact": ["Story Elements Interact", "Setting, characters and plot shape one another.", ["Setting can create conflict (a storm, a strict school).", "Characters' choices drive the plot.", "Events change characters."], "How might a blizzard setting shape a story's plot?", ["The blizzard traps characters together.", "This forces conflicts and choices.", "Setting drives the plot."], "Ask: Could this story happen anywhere else?"],
  "Characters' points of view": ["Characters' Points of View", "Different characters see the same events differently.", ["Each character has their own feelings and goals.", "Authors contrast views to create conflict or humor.", "Readers may know more than any one character."], "A boy thinks his neighbor is rude; the neighbor is just ill. How do their views differ?", ["The boy judges by behavior.", "The neighbor is coping with illness.", "Their views clash until the boy learns the truth."], "Retell an event from another character's view."],
  "Poetry: form and meaning": ["Poetry: Form and Meaning", "A poem's form, like its lines, stanzas, rhyme and rhythm, helps create its meaning.", ["Stanzas group ideas like paragraphs.", "Line breaks create pauses and emphasis.", "Repetition highlights important ideas.", "Sonnets, haiku and free verse are different forms."], "Why might a poet end a poem with a very short line?", ["A short line stands out.", "It adds emphasis or surprise."], "Read poems aloud to hear the rhythm."],
  "How a drama is built": ["How Drama Works", "Plays are written to be performed.", ["A cast list names the characters.", "Acts and scenes divide the play.", "Dialogue tells the story; stage directions (often in italics or parentheses) guide actors.", "There is usually no narrator."], "What do the words in parentheses in a script do?", ["They are stage directions.", "They tell actors how to move or speak."], "Picture the scene on a stage as you read."],
  "Fiction and history compared": ["Fiction and History", "Historical fiction mixes real events with invented characters.", ["Authors may change or add details for the story.", "Compare the story with a factual source.", "Ask why the author changed things."], "A story about the Galveston hurricane has a fictional boy. What can a factual article add?", ["Exact dates, death tolls and causes.", "The story gives feelings; the article gives facts."], "Use fiction to feel history and nonfiction to check it."],
  "The strongest evidence": ["The Strongest Evidence", "Not all evidence is equal. Choose the quote that proves your point most directly.", ["Strong evidence clearly connects to the claim.", "Specific details beat general ones.", "Avoid evidence that needs too much explaining."], "Claim: the town recovered after the flood. Which is stronger: \"Life went on\" or \"Within a year, every shop had reopened\"?", ["The second is specific and measurable.", "It is stronger evidence."], "If your evidence could support several different claims, it's probably too weak."],
  "Theme and its development": ["Developing Theme", "Strong stories build a theme through conflict, choices and change.", ["Identify the central conflict.", "Notice the character's key decisions.", "Connect the ending to a lesson about life.", "Objective summaries leave out your opinions."], "A lighthouse keeper's job is automated, but he saves ships when the power fails. Theme?", ["Machines replace his work.", "His care is still needed.", "Theme: human care can't be fully replaced."], "Support the theme with details from several points in the story."],
  "Dialogue and plot": ["Dialogue and Plot", "Dialogue moves the plot, reveals character and creates tension.", ["A line can introduce a problem.", "Arguments create conflict.", "How characters talk shows who they are."], "\"We're coming home early!\" Dad says on the phone. How does this affect the plot?", ["It creates a new problem.", "The surprise party may be ruined, so tension rises."], "Ask: What changes because of this line?"],
  "Dramatic irony": ["Irony", "Irony is a gap between what is expected and what happens.", ["Dramatic irony: the reader knows something a character doesn't.", "Situational irony: the outcome is the opposite of what's expected.", "Verbal irony: saying the opposite of what you mean.", "Dramatic irony creates suspense or humor."], "Readers know the hero's friend secretly fixed his robot, but he brags his design is \"unbreakable.\" What irony is this?", ["We know the truth; he doesn't.", "Dramatic irony."], "Ask: What do I know that the character doesn't?"],
  "Modern stories from old myths": ["Myths in Modern Stories", "Many modern stories borrow plots, characters and themes from myths.", ["Look for familiar patterns: a proud hero, a trickster, a quest.", "Compare how the modern version changes details.", "Themes often stay the same."], "A modern story has a student who brags she's better than her teacher. Which myth does it echo?", ["Arachne boasted she weaved better than Athena.", "Both show pride before a fall."], "Ask: What stayed the same, and what changed?"],

  /* ---------- reading informational text ---------- */
  "Tracing an argument": ["Tracing an Argument", "Follow an argument from claim to reasons to evidence.", ["Find the claim: the author's position.", "List each reason.", "Match evidence to each reason.", "Notice counterclaims and responses."], "An essay claims schools should start later because teens need more sleep, citing a study. Trace it.", ["Claim: start later.", "Reason: teens need sleep.", "Evidence: a study."], "Make an outline: claim → reasons → evidence."],
  "Evaluating claims": ["Evaluating Claims", "Decide whether a claim is supported by good reasons and evidence.", ["Is the evidence relevant?", "Is it sufficient (enough)?", "Is it from a reliable source?", "Watch for opinions dressed as facts."], "Claim: \"Video games improve grades.\" Evidence: \"My friend plays and has A's.\" Is it strong?", ["One example isn't enough.", "The claim is weakly supported."], "Ask: Would this convince someone who disagrees?"],
  "Evaluating evidence": ["Evaluating Evidence", "Good evidence is relevant, sufficient and credible.", ["Relevant: it connects to the claim.", "Sufficient: there's enough of it.", "Credible: it comes from a trustworthy source."], "Which is better evidence for \"Recycling saves money\": a city budget report or a neighbor's guess?", ["The budget report has real data.", "It is relevant and credible."], "Numbers and expert sources usually beat personal stories."],
  "Evaluating arguments": ["Evaluating Arguments", "Judge whether an argument's reasoning is sound and its evidence strong.", ["Is each reason supported?", "Is any reasoning flawed (like a fallacy)?", "Does the author answer counterclaims fairly?", "Is any important evidence missing?"], "An essay says, \"Everyone is getting a phone, so you should too.\" What is the flaw?", ["\"Everyone is doing it\" is the bandwagon fallacy.", "It isn't a real reason."], "Look for gaps between the evidence and the conclusion."],
  "How people, events and ideas interact": ["How Ideas Interact", "In informational texts, people shape events and events shape ideas.", ["Look for cause-and-effect links.", "Notice how a person's actions changed events.", "See how events changed people's thinking."], "How did railroads affect Texas towns?", ["Towns with stations grew.", "Towns without them faded.", "An invention changed where people lived."], "Draw a chain: person → event → effect."],
  "Developing a central idea": ["Developing a Central Idea", "Authors develop a central idea across paragraphs.", ["The introduction states or hints at the idea.", "Body paragraphs add evidence and examples.", "Analogies and comparisons help explain complex points.", "The conclusion reinforces it."], "An article compares the brain to a city to explain learning. How does this develop the idea?", ["The analogy makes complex brain science easier.", "Each paragraph adds one part of the comparison."], "Track what each paragraph adds."],
  "Analogies and comparisons": ["Analogies and Comparisons", "Authors use analogies to explain unfamiliar ideas with familiar ones.", ["An analogy compares two things that work in similar ways.", "It makes complex ideas easier to picture.", "No analogy is perfect; notice its limits."], "\"Your heart is a pump.\" What does this analogy explain?", ["A pump pushes liquid through pipes.", "The heart pushes blood through blood vessels."], "Ask: How are these two things alike?"],
  "Paragraph structure": ["Paragraph Structure", "Each paragraph has a job and a structure.", ["The topic sentence states the main idea.", "Supporting sentences give details and evidence.", "A concluding or transition sentence links to the next idea.", "Key sentences refine a concept."], "Which sentence usually states a paragraph's main idea?", ["The topic sentence.", "It is often, but not always, the first sentence."], "Underline the topic sentence of each paragraph."],
  "Conflicting information": ["Conflicting Information", "Sometimes sources disagree. Good readers figure out why.", ["Find exactly where the sources disagree.", "Compare their evidence.", "Consider each source's purpose and possible bias.", "Look for more sources to settle it."], "A newspaper blames a factory for a fish kill; a water lab finds low oxygen. Which is more trustworthy?", ["The lab used test results.", "The newspaper used opinions.", "The lab report is more trustworthy for now."], "Facts can be checked; opinions can't."],
  "Comparing text structures": ["Comparing Text Structures", "Different texts about the same topic may be organized differently.", ["Chronological, cause and effect, compare and contrast, problem and solution.", "Structure affects what readers notice.", "Compare how each structure serves its purpose."], "One article tells a storm's events hour by hour; another explains its causes. Compare them.", ["The first is chronological.", "The second is cause and effect.", "Each highlights different information."], "Look at transition words to identify structure."],
  "Evaluating media": ["Evaluating Media", "Videos, photos, charts and headlines all try to inform or persuade.", ["Who made it, and why?", "What does it include and leave out?", "How do images, music or headlines shape your feelings?"], "A headline reads \"Factory Poisons Lake\" before tests are done. What's the problem?", ["It states blame without evidence.", "It may mislead readers."], "Compare the same story across different media."],
  "Charts and media": ["Charts and Media", "Charts, graphs and other media present information visually.", ["Read the title, labels and units first.", "Compare bars or values.", "Ask what the visual adds to the text."], "A chart shows video watching at 2 hours and homework at 1 hour. What can you conclude?", ["Videos take twice as much time as homework."], "Check whether a chart supports the author's claim."],
  "Comparing genres": ["Comparing Genres", "Different genres can explore the same topic or theme in different ways.", ["Fiction tells stories; poems use compact language; dramas use dialogue and stage directions.", "Informational texts present facts.", "Compare how each genre handles the theme."], "A poem and a short story are both about growing up. How might they differ?", ["The poem uses images and few words.", "The story uses plot and dialogue."], "Ask: What can this genre do that the other can't?"],
  "Word choice and tone": ["Word Choice and Tone", "Authors choose words carefully to create tone: their attitude toward a subject.", ["Tone words: cheerful, bitter, sarcastic, hopeful, serious.", "Connotations shape tone.", "Figurative language adds feeling."], "\"The tiny house huddled beneath the storm.\" What tone is created?", ["\"Huddled\" suggests fear and smallness.", "The tone is anxious."], "Circle the most powerful words in a passage."],

  /* ---------- vocabulary ---------- */
  "Figurative language and personification": ["Figurative Language", "Figurative language makes writing vivid by meaning more than the literal words.", ["Simile: compares with like or as.", "Metaphor: says one thing is another.", "Personification: gives human qualities to things.", "Hyperbole: exaggerates for effect."], "\"The wind whispered secrets.\" What is it?", ["Wind can't whisper; that's a human action.", "Personification."], "Ask what feeling the comparison creates."],
  "Connotation and denotation": ["Connotation and Denotation", "Words have a dictionary meaning and an emotional meaning.", ["Denotation: the literal definition.", "Connotation: the feelings a word suggests.", "\"Thrifty\" (positive) vs. \"cheap\" (negative)."], "Which sounds more positive: \"childlike\" or \"childish\"?", ["Childlike suggests innocence.", "Childish suggests immaturity.", "Childlike is more positive."], "Swap a word and see how the feeling changes."],
  "Connotation": ["Connotation", "Connotation is the feeling a word carries beyond its definition.", ["Positive, negative or neutral.", "Authors pick words to shape readers' feelings.", "\"Mob\" vs. \"crowd\" vs. \"gathering.\""], "Why would a writer call a group of fans a \"mob\"?", ["Mob suggests danger and disorder.", "The writer wants readers to see them negatively."], "Think about synonyms and how they feel different."],
  "Context and affixes": ["Context and Affixes", "Use context clues and word parts to figure out new words.", ["Context: definitions, examples, contrasts nearby.", "Prefixes change meaning: un-, re-, pre-, mis-.", "Suffixes change part of speech: -tion, -ous, -ly.", "Roots carry the core meaning."], "What does \"misinterpret\" mean?", ["mis- = wrongly.", "interpret = understand or explain.", "Misinterpret = understand wrongly."], "Combine clues from the sentence and the word parts."],
  "Analogies": ["Analogies", "An analogy shows a relationship between two pairs of words.", ["Find the relationship in the first pair: opposite, part-whole, tool-user, cause-effect.", "Apply the same relationship to the second pair.", "Read it as \"A is to B as C is to D.\""], "Bird is to nest as bee is to ___.", ["A bird lives in a nest.", "A bee lives in a hive.", "hive."], "Make a sentence for the first pair, then test it on the second."],
  "Figurative language and allusions": ["Allusions", "An allusion is a brief reference to a well-known story, person or event.", ["Allusions come from myths, the Bible, history, literature and pop culture.", "They pack lots of meaning into a few words.", "\"Herculean task\" means a very hard job."], "\"Her smile was her Achilles' heel.\" What does it mean?", ["Achilles was weak only in his heel.", "Her smile was her weak spot."], "If you don't recognize an allusion, look it up."],
  "Verbal irony and puns": ["Verbal Irony and Puns", "Wordplay adds humor and meaning.", ["Verbal irony: saying the opposite of what you mean.", "Sarcasm is a sharp form of verbal irony.", "A pun plays on a word with two meanings or sounds."], "\"I'm reading a book about anti-gravity. It's impossible to put down.\" Why is this a pun?", ["\"Put down\" means stop reading and also lower something.", "Anti-gravity makes both meanings funny."], "Look for words with double meanings."],
  "Word relationships": ["Word Relationships", "Understanding how words relate helps you learn new ones.", ["Synonyms and antonyms.", "Part to whole: page → book.", "Category: oak → tree.", "Degree: warm → hot → scorching."], "Put in order from weakest to strongest: furious, annoyed, angry.", ["annoyed, angry, furious."], "Use a word line to rank similar words."],

  /* ---------- grammar ---------- */
  "Intensive pronouns": ["Intensive Pronouns", "Intensive pronouns add emphasis: myself, yourself, himself, herself, itself, ourselves, themselves.", ["They follow the noun or pronoun they emphasize.", "The sentence still works without them.", "Reflexive pronouns look the same but are needed."], "\"The principal herself greeted us.\" Intensive or reflexive?", ["Remove \"herself\": The principal greeted us.", "Still correct, so it's intensive."], "Never use hisself or theirselves."],
  "Shifts in pronoun number and person": ["Pronoun Consistency", "Keep pronouns consistent in number and person.", ["Number: singular vs. plural.", "Person: first (I, we), second (you), third (he, she, they).", "Don't switch from \"a student\" to \"you\" in the same sentence."], "Fix: \"When a person exercises, you feel better.\"", ["A person is third person; you is second person.", "When people exercise, they feel better."], "Circle every pronoun and check what it refers to."],
  "Vague pronouns": ["Vague Pronouns", "A pronoun is vague when the reader can't tell what it refers to.", ["\"Sam told Leo he won\": who won?", "\"They say…\": who says?", "Fix by using the noun instead."], "Fix: \"Mia called Ava after she got home.\"", ["\"She\" could be Mia or Ava.", "Mia called Ava after Mia got home."], "Ask: Could this pronoun mean two things?"],
  "Phrases and clauses": ["Phrases and Clauses", "Clauses have a subject and a verb; phrases don't.", ["Independent clause: can stand alone.", "Dependent clause: starts with a word like because, when, although.", "Phrases add details: prepositional, participial and others."], "Is \"because the bus was late\" a phrase or a clause?", ["It has a subject (bus) and verb (was).", "It starts with because.", "It's a dependent clause."], "Look for a subject + verb pair."],
  "Simple, compound and complex sentences": ["Sentence Types", "Sentences are built from clauses in different ways.", ["Simple: one independent clause.", "Compound: two independent clauses joined (and, but, so, ;).", "Complex: an independent clause and a dependent clause.", "Compound-complex: two independent clauses plus a dependent clause."], "\"When it rained, we played inside.\" What type?", ["\"When it rained\" is dependent.", "\"we played inside\" is independent.", "Complex."], "Mix sentence types to make writing flow."],
  "Misplaced and dangling modifiers": ["Modifiers", "Put describing words right next to what they describe.", ["Misplaced: in the wrong spot (\"I saw a dog with binoculars\").", "Dangling: what it describes is missing (\"Walking home, the rain started\").", "Fix by moving the modifier or adding the missing noun."], "Fix: \"Running to class, my backpack ripped.\"", ["The backpack wasn't running.", "Running to class, I ripped my backpack."], "Ask: Who or what is doing this?"],
  "Commas with coordinate adjectives": ["Coordinate Adjectives", "Use a comma between adjectives that describe a noun equally.", ["Test 1: switch their order.", "Test 2: put \"and\" between them.", "If both tests sound right, use a comma."], "\"a long, boring movie\" or \"a long boring movie\"?", ["\"a boring, long movie\" works; \"long and boring\" works.", "Use the comma: a long, boring movie."], "Numbers and colors often don't need commas: \"three red balloons.\""],
  "Gerunds, participles and infinitives": ["Verbals", "Verbals are verb forms that act as other parts of speech.", ["Gerund: -ing verb used as a noun (Swimming is fun).", "Participle: verb form used as an adjective (the barking dog, the broken vase).", "Infinitive: to + verb (I want to win)."], "In \"The crying baby fell asleep,\" what is \"crying\"?", ["It describes the baby.", "It's a participle."], "Ask what job the word does in the sentence."],
  "Active and passive voice": ["Active and Passive Voice", "Voice shows whether the subject does or receives the action.", ["Active: The dog chased the cat.", "Passive: The cat was chased by the dog.", "Active is usually clearer; passive is useful when the doer is unknown."], "Change to active: \"The window was broken by the ball.\"", ["Who did it? The ball.", "The ball broke the window."], "Passive voice often uses a form of \"be\" + past participle."],
  "Verb moods": ["Verb Moods", "Verb mood shows the speaker's attitude.", ["Indicative: states facts (She sings).", "Imperative: commands (Sing!).", "Interrogative: asks (Does she sing?).", "Conditional: if-then (If she sings, we'll listen).", "Subjunctive: wishes or unreal situations (If I were you…)."], "\"If I were a bird, I would fly.\" What mood?", ["It describes something not true.", "Subjunctive."], "Use \"were\" for wishes, even with I, he and she."],
  "Shifts in voice and mood": ["Consistent Voice and Mood", "Avoid switching voice or mood without a reason.", ["Don't mix active and passive in one sentence.", "Don't mix commands with statements.", "Consistency makes writing clear."], "Fix: \"Preheat the oven, and then the batter should be poured.\"", ["The first part is imperative; the second is indicative and passive.", "Preheat the oven, and then pour the batter."], "Read instructions aloud to catch shifts."],

  /* ---------- punctuation, spelling and style ---------- */
  "Punctuation for extra information": ["Setting Off Extra Information", "Commas, parentheses and dashes set off information that isn't essential.", ["Commas: normal emphasis (My sister, a nurse, works nights).", "Parentheses: low emphasis, an aside.", "Dashes: strong emphasis or a sudden break.", "Use them in pairs around mid-sentence information."], "Add punctuation: \"Our dog a beagle loves walks.\"", ["\"a beagle\" is extra information.", "Our dog, a beagle, loves walks."], "Remove the extra part; the sentence should still work."],
  "Commas, ellipses and dashes": ["Commas, Ellipses and Dashes", "These marks show pauses, breaks and omissions.", ["Comma: a short pause or separation.", "Ellipsis (…): a pause, trailing off, or words left out of a quote.", "Dash (—): a sudden break or emphasis."], "Use an ellipsis to show hesitation: \"I think we should go.\"", ["\"I think… we should go.\""], "Don't overuse dashes and ellipses; they lose power."],
  "Spelling": ["Spelling Tricky Words", "Many words follow patterns; others must be memorized.", ["i before e except after c: receive, believe (with exceptions like weird).", "Double the final consonant before -ing or -ed in short words: occur → occurred.", "Watch for silent letters and double letters: necessary, embarrass.", "Affect is usually a verb; effect is usually a noun."], "Spell the past tense of \"occur.\"", ["Occur ends with one vowel + one consonant and is stressed at the end.", "Double the r: occurred."], "Keep a personal list of words you misspell."],
  "Varying sentence patterns": ["Varying Sentences", "Varied sentences keep readers interested.", ["Mix short and long sentences.", "Start some sentences with phrases or clauses.", "Combine choppy sentences."], "Revise: \"I ran. I was late. I missed the bus.\"", ["Combine: Running late, I missed the bus."], "Read aloud; if it sounds choppy or monotonous, vary it."],
  "Sentence variety": ["Sentence Variety", "Strong writers vary sentence structure for effect.", ["Short sentences add punch.", "Long sentences show flow and connection.", "Begin with participial or prepositional phrases sometimes.", "Use different sentence types."], "Revise for variety: \"The storm came. It was loud. Trees fell.\"", ["The storm roared in, and trees crashed down. Then silence."], "Look at the first word of each sentence. Are many the same?"],
  "Consistent style and tone": ["Consistent Style and Tone", "Keep your writing's style and tone steady.", ["Formal writing avoids slang and contractions.", "Pick a tone (serious, friendly) and stick with it.", "A sudden casual phrase in a formal essay stands out."], "Fix: \"The experiment showed clear results, and it was totally awesome.\"", ["\"Totally awesome\" is too casual.", "The experiment showed clear, impressive results."], "Read your work as your audience would."],
  "Formal style": ["Formal Style", "Formal style is used for essays, reports and speeches.", ["Avoid slang, contractions and casual phrases.", "Use precise vocabulary.", "Keep an objective tone."], "Make formal: \"Lots of kids think recess is super important.\"", ["Many students believe recess is very important."], "Imagine you're writing to a principal or a judge."],
  "Concise language": ["Concise Language", "Concise writing says more with fewer words.", ["Cut words that repeat an idea.", "Replace long phrases with single words.", "Remove empty words like \"really\" and \"very.\""], "Make concise: \"At this point in time, we are now ready.\"", ["\"At this point in time\" = now.", "We are ready now."], "Every word should earn its place."],
  "Cutting wordiness": ["Cutting Wordiness", "Wordy sentences hide your ideas.", ["Due to the fact that → because.", "In order to → to.", "Remove redundancies: \"true facts,\" \"past history.\""], "Revise: \"In order to win, we need to work together as a team.\"", ["To win, we need to work as a team."], "Read each sentence and ask: can I say this shorter?"],
  "Precise word choice": ["Precise Word Choice", "Exact words make writing clear and powerful.", ["Replace vague words (good, bad, thing, stuff).", "Use strong verbs instead of verb + adverb.", "Choose words with the right connotation."], "Improve: \"The dog walked slowly.\"", ["\"Walked slowly\" can be one precise verb.", "The dog trudged."], "A thesaurus helps, but check the connotation."],

  /* ---------- research ---------- */
  "Gathering sources": ["Gathering Sources", "Good research uses several reliable sources.", ["Use library databases, books and trusted websites.", "Use search terms that are specific.", "Record each source's author, title and date as you go."], "Which search would find better results: \"animals\" or \"how sea turtles navigate\"?", ["The specific search narrows results.", "\"how sea turtles navigate\" is better."], "Keep a running source list from the start."],
  "Paraphrasing and quoting": ["Paraphrasing and Quoting", "Use sources in your own words or with exact quotes, and always give credit.", ["Paraphrase: same idea, your words.", "Quote: exact words in quotation marks.", "Cite both."], "Paraphrase: \"Sea otters use rocks as tools to crack shells.\"", ["Sea otters crack open shellfish with stones."], "Read, cover the source, then write from memory."],
  "Credible sources": ["Credible Sources", "Trust sources that are accurate, current and unbiased.", ["Check the author's expertise.", "Check the date.", "Look for cited evidence.", "Watch for bias and ads."], "Which is more credible: a .gov health page or an anonymous blog?", ["The .gov page is reviewed by experts.", "It is more credible."], "When in doubt, check another source."],
  "Citing sources": ["Citing Sources", "Citations give credit and help readers find your sources.", ["In-text: (Author page) or \"According to…\".", "Works cited: author, title, publisher, date.", "Cite quotes, paraphrases and unique facts."], "Do you cite a paraphrased fact?", ["Yes, the idea came from someone else."], "Common knowledge doesn't need a citation."],
  "Research questions": ["Research Questions", "A good research question guides your research.", ["It is focused, not too broad or narrow.", "It can't be answered with yes or no.", "It needs several sources to answer.", "Refocus it as you learn."], "Improve: \"What about space?\"", ["Too broad.", "Better: How do astronauts stay healthy on long missions?"], "Start with how or why."],
  "Evaluating sources": ["Evaluating Sources", "Not all sources are equally trustworthy.", ["Authority: who wrote it?", "Accuracy: are facts supported?", "Objectivity: is it biased?", "Currency: is it up to date?"], "A drink company's website says its drink improves grades. Is it reliable?", ["The company profits from sales.", "It's biased; find independent research."], "Ask who benefits from the information."],
  "Assessing sources": ["Assessing Sources", "Judge each source before using it.", ["Check the author and publisher.", "Check for evidence and citations.", "Compare with other sources.", "Notice purpose: inform, persuade or sell?"], "Two sources disagree. What should you do?", ["Compare their evidence.", "Look for a third reliable source."], "Write a one-line note on each source's reliability."],
  "Using quotations": ["Using Quotations", "Quotations should support your ideas, not replace them.", ["Introduce the quote: According to…", "Copy words exactly and use quotation marks.", "Explain the quote after you use it.", "Use ellipses to shorten carefully."], "How should you introduce a quote from a scientist?", ["\"Dr. Lee, a marine biologist, explains, '…'\""], "Sandwich quotes: introduce, quote, explain."],
  "Avoiding plagiarism": ["Avoiding Plagiarism", "Plagiarism is using others' words or ideas without credit.", ["Quote exact words with quotation marks.", "Paraphrase truly in your own words.", "Cite every source you use."], "Is changing a few words in a copied sentence okay without a citation?", ["No. It's still someone else's idea and structure.", "Paraphrase fully and cite."], "Take notes in your own words from the start."],
  "Citation": ["Citation", "A citation tells readers exactly where information came from.", ["Include author, title, source and date.", "Follow a style like MLA.", "Match in-text citations to your works-cited list."], "What goes first in an MLA works-cited entry?", ["The author's last name."], "Use a consistent format for every source."],
  "Combining information": ["Combining Information", "Synthesizing means combining sources into your own understanding.", ["Group notes by subtopic, not by source.", "Show where sources agree or differ.", "Add your own analysis."], "Two sources both say coral reefs are bleaching from warm water. How can you combine them?", ["Both NASA and a university study report that warming water bleaches reefs."], "Use phrases like \"Both sources show…\" and \"Unlike Source A…\""],

  /* ---------- writing ---------- */
  "Argument essays": ["Argument Essays", "An argument convinces readers with logic and evidence.", ["State a clear, debatable claim.", "Support it with reasons and credible evidence.", "Address a counterclaim.", "Conclude by reinforcing your claim."], "Which is a strong claim: \"Pets are nice\" or \"Schools should allow therapy dogs because they reduce stress\"?", ["The second is debatable and gives a reason."], "Evidence beats emotion."],
  "Arguments with counterclaims": ["Counterclaims", "Strong arguments answer the other side.", ["State the opposing view fairly.", "Rebut it with evidence.", "Use transitions: Some argue…; however…"], "Counterclaim: \"Uniforms limit self-expression.\" Write a rebuttal.", ["However, students can express themselves through clubs, art and accessories, while uniforms reduce peer pressure."], "Acknowledging the other side makes you more convincing."],
  "english:6:Informative essays": ["Informative Essays", "Informative essays explain a topic clearly.", ["Introduce the topic with a thesis.", "Organize body paragraphs by subtopic.", "Use facts, definitions and examples.", "Conclude by summarizing the importance."], "Write a thesis for an essay on volcanoes.", ["Volcanoes form when magma escapes through Earth's crust, and they shape landscapes and lives."], "Each paragraph needs a clear topic sentence."],
  "Explanatory essays": ["Explanatory Essays", "Explanatory essays explain how or why something happens.", ["Thesis: what you'll explain.", "Logical order: steps, causes or categories.", "Precise vocabulary and transitions.", "Visuals or headings can help."], "Which transition shows a cause? \"therefore\" or \"for example\"?", ["\"Therefore\" signals a result or cause."], "Explain as if your reader knows nothing about the topic."],
  "Organized informative writing": ["Organizing Informative Writing", "Structure helps readers learn.", ["Use headings for sections.", "Group related details.", "Use transitions to connect ideas.", "Choose a structure: compare, cause and effect, or sequence."], "How would you organize an essay comparing frogs and toads?", ["Compare and contrast: likenesses, then differences."], "Outline before you draft."],
  "Narratives": ["Writing Narratives", "Narratives tell a story with a clear beginning, middle and end.", ["Hook the reader.", "Develop characters with dialogue and action.", "Use sensory details.", "Build to a climax and resolve it."], "Write a hook for a story about a lost dog.", ["\"The leash was still in my hand, but the other end was empty.\""], "Show, don't tell."],
  "Narrative pacing": ["Pacing", "Pacing controls how fast a story feels.", ["Slow down important moments with detail.", "Speed up with short sentences and time jumps.", "Use transitions: Meanwhile, Hours later…"], "How can you slow down the moment before a big race?", ["Describe the heartbeat, the crowd and the starting line in detail."], "Spend the most words on the most important moments."],
  "Narratives with reflection": ["Reflective Narratives", "Reflection shows what a story means to the narrator.", ["Tell the events.", "Show the narrator's thoughts and feelings.", "End with what was learned or how they changed."], "Write a reflective ending for a story about losing a game.", ["\"Looking back, I learned that how I played mattered more than the score.\""], "Ask: Why does this story matter to me?"],
  "Revising for clarity": ["Revising for Clarity", "Revision makes ideas clear and organized.", ["Cut sentences that don't support the main idea.", "Replace vague words.", "Add transitions.", "Check that the order makes sense."], "Revise: \"The thing about the project was good.\"", ["\"The project's design was creative and well-planned.\""], "Read your draft aloud to a partner."],
  "Editing and proofreading": ["Editing and Proofreading", "Editing fixes grammar, spelling and punctuation.", ["Check subject-verb agreement.", "Check spelling and capitalization.", "Check punctuation, especially commas.", "Read slowly, even backward, to catch errors."], "Find the error: \"The list of chores are long.\"", ["List is singular.", "The list of chores is long."], "Edit in several passes, each looking for one kind of mistake."],

  /* ---------- Grade 8 review weeks ---------- */
  "english:8:Year review": ["Grade 8 Review", "Let's practice the big skills from Grade 8 English!", ["Find theme and the strongest evidence.", "Evaluate arguments and sources.", "Use active voice and consistent mood.", "Punctuate with commas, ellipses and dashes.", "Cite your sources."], "Change to active voice: \"The essay was written by Ava.\"", ["Ava wrote the essay."], "Mix skills: read closely, write clearly, check carefully."],
  "Review: Literature and Informational text": ["Review: Reading", "Review reading literature and informational texts.", ["Theme develops through conflict and change.", "Dialogue reveals character and moves the plot.", "Central ideas are supported by key details.", "Evaluate arguments for strong evidence."], "Which is the strongest evidence that a character is brave?", ["Look for an action, like running into a burning barn to save a calf."], "Answer, cite, explain."],
  "Review: Vocabulary and Grammar": ["Review: Words and Grammar", "Review roots, word meanings and grammar.", ["Roots and affixes unlock meanings.", "Connotation shapes tone.", "Gerunds, participles, infinitives.", "Active vs. passive voice; verb moods."], "What does \"bio\" mean in \"biography\"?", ["life."], "Practice a few of each type."],
  "Review: Punctuation and style and Reading closely": ["Review: Style and Close Reading", "Review punctuation, style and close reading.", ["Commas, ellipses and dashes.", "Formal style and sentence variety.", "Conflicting information and media.", "Myths in modern stories."], "Add a dash for emphasis: \"There was only one answer cake.\"", ["There was only one answer—cake."], "Read questions carefully before answering."],
  "Review: Research and Writing": ["Review: Research and Writing", "Review research and writing skills.", ["Ask focused research questions.", "Use credible sources and cite them.", "Write arguments with counterclaims.", "Write explanatory and reflective narratives."], "Which is a better research question: \"Are dogs good?\" or \"How do service dogs help veterans?\"", ["The second is focused and researchable."], "Plan before you write."],
};
